package edu.pe.cibertec.saibm.usuario.infrastructure.in.rest; import java.net.URI; import java.util.stream.Collectors; import jakarta.servlet.http.HttpServletRequest; import org.springframework.http.*; import org.springframework.web.bind.MethodArgumentNotValidException; import org.springframework.web.bind.annotation.*; import edu.pe.cibertec.saibm.usuario.domain.exception.UserNotFoundException; @RestControllerAdvice public class UserExceptionHandler {@ExceptionHandler(UserNotFoundException.class)ProblemDetail missing(HttpServletRequest r){return p(HttpStatus.NOT_FOUND,"User not found",r);}@ExceptionHandler(WriteAuthorizationException.class)ProblemDetail forbidden(HttpServletRequest r){return p(HttpStatus.FORBIDDEN,"Forbidden",r);}@ExceptionHandler(IllegalStateException.class)ProblemDetail conflict(HttpServletRequest r){return p(HttpStatus.CONFLICT,"User conflict",r);}@ExceptionHandler({IllegalArgumentException.class,InvalidRequestException.class})ProblemDetail invalid(HttpServletRequest r){return p(HttpStatus.BAD_REQUEST,"Invalid request",r);}@ExceptionHandler(MethodArgumentNotValidException.class)ProblemDetail validation(MethodArgumentNotValidException e,HttpServletRequest r){var x=p(HttpStatus.BAD_REQUEST,"Invalid request",r);x.setProperty("errors",e.getBindingResult().getFieldErrors().stream().collect(Collectors.toMap(a->a.getField(),a->a.getDefaultMessage(),(a,b)->a)));return x;}private ProblemDetail p(HttpStatus s,String t,HttpServletRequest r){var p=ProblemDetail.forStatusAndDetail(s,t);p.setTitle(t);p.setType(URI.create("urn:saibm:usuario:"+s.value()));p.setInstance(URI.create(r.getRequestURI()));return p;}}
